def consulta(G, adr_id):
    decisions = []
    repository = None
    for _, target, data in G.out_edges(adr_id, data=True):
        rel = data.get("relation")
        if rel == "recordsDecision":
            desc = G.nodes[target].get("decisionDescription")
            decisions.append((target, desc))
        elif rel == "belongsToRepository":
            repo_name = G.nodes[target].get("repositoryName")
            repository = (target, repo_name)
    return {"adr": adr_id, "decisions": decisions, "repository": repository}

