def consulta(G):
    resultados = []
    for adr, data in G.nodes(data=True):
        if data.get("type") == "ArchitectureDecisionRecord":
            fecha = data.get("recordDate")
            for _, status_decl, edge_data in G.out_edges(adr, data=True):
                if edge_data.get("relation") == "hasStatusDeclaration":
                    status_data = G.nodes[status_decl]
                    raw_literal = status_data.get("rawStatusLiteral")
                    norm_status = None
                    for _, norm, norm_edge in G.out_edges(status_decl, data=True):
                        if norm_edge.get("relation") == "hasNormalizedStatus":
                            norm_status = norm
                    resultados.append({
                        "adr": adr,
                        "recordDate": fecha,
                        "statusDeclaration": status_decl,
                        "rawStatusLiteral": raw_literal,
                        "normalizedStatus": norm_status
                    })
    return resultados

def consulta(G, adr_node):
    topics = [target for _, target, data in G.out_edges(adr_node, data=True) if data.get('relation') == 'addressesTopic']
    repos = [target for _, target, data in G.out_edges(adr_node, data=True) if data.get('relation') == 'belongsToRepository']
    result = []
    for topic in topics:
        topic_name = G.nodes[topic].get('topicName', topic)
        same_topic_adrs = []
        for repo in repos:
            repo_adrs = [src for src, _, data in G.in_edges(repo, data=True) if data.get('relation') == 'belongsToRepository' and src != adr_node]
            for other_adr in repo_adrs:
                adr_topics = [t for _, t, d in G.out_edges(other_adr, data=True) if d.get('relation') == 'addressesTopic']
                if topic in adr_topics:
                    same_topic_adrs.append(other_adr)
        result.append({'topic': topic_name, 'other_adrs': same_topic_adrs})
    return result

def consulta(G):
    replaces_relations = {}
    for node, data in G.nodes(data=True):
        if data.get('type') == 'RelationDeclaration':
            rel_type = (data.get('relationType') or '').lower()
            if 'supersede' in rel_type or 'replace' in rel_type:
                sources = set()
                targets = set()
                declarers = set()
                for u, v, k, edata in G.in_edges(node, keys=True, data=True):
                    rel = edata.get('relation')
                    if rel == 'sourceADR':
                        sources.add(u)
                    elif rel == 'targetADR':
                        targets.add(u)
                    elif rel == 'declaresRelation':
                        declarers.add(u)
                for u, v, k, edata in G.out_edges(node, keys=True, data=True):
                    rel = edata.get('relation')
                    if rel == 'sourceADR':
                        sources.add(v)
                    elif rel == 'targetADR':
                        targets.add(v)
                for s in sources:
                    for t in targets:
                        pair = (s, t)
                        if pair not in replaces_relations:
                            replaces_relations[pair] = set()
                        replaces_relations[pair].update(declarers)
    results = []
    for (source, target), decls in replaces_relations.items():
        results.append({
            'replacing_adr': source,
            'replaced_adr': target,
            'declared_by': list(decls),
            'declared_by_both': len(decls) >= 2
        })
    return results

def consulta(G):
    # Encontrar relaciones de tipo 'amends' entre ADRs
    # donde el ADR enmendado no haya sido reemplazado/superado.
    amendments = []
    # Identificar todas las declaraciones de reemplazo para saber qué ADRs no están vigentes
    replaced_adrs = set()
    for rel, data in G.nodes(data=True):
        if data.get('type') == 'RelationDeclaration':
            rtype = data.get('relationType', '').lower()
            if rtype in ['supersedes', 'replaces']:
                for u, v, k, edata in G.in_edges(rel, data=True, keys=True):
                    if edata.get('relation') == 'targetADR':
                        replaced_adrs.add(u)
                for u, v, k, edata in G.out_edges(rel, data=True, keys=True):
                    if edata.get('relation') == 'targetADR':
                        replaced_adrs.add(v)

    for rel, data in G.nodes(data=True):
        if data.get('type') == 'RelationDeclaration':
            rtype = data.get('relationType', '').lower()
            if 'amend' in rtype:
                # Obtener source y target
                sources = [u for u, v, edata in G.in_edges(rel, data=True) if edata.get('relation') == 'sourceADR'] + \
                          [v for u, v, edata in G.out_edges(rel, data=True) if edata.get('relation') == 'sourceADR']
                targets = [u for u, v, edata in G.in_edges(rel, data=True) if edata.get('relation') == 'targetADR'] + \
                          [v for u, v, edata in G.out_edges(rel, data=True) if edata.get('relation') == 'targetADR']
                for s in sources:
                    for t in targets:
                        if t not in replaced_adrs:
                            amendments.append((s, t))
    return list(set(amendments))

def consulta(G, adr_id, target_date):
    # Obtener fecha y estado original del ADR
    adr_date = G.nodes[adr_id].get('recordDate')
    status = None
    for _, status_decl, d in G.out_edges(adr_id, data=True):
        if d.get('relation') == 'hasStatusDeclaration':
            for _, norm_status, d2 in G.out_edges(status_decl, data=True):
                if d2.get('relation') == 'hasNormalizedStatus':
                    status = norm_status

    if adr_date and target_date < adr_date:
        return 'not_yet_recorded'

    # Comprobar si fue reemplazado antes o en la fecha dada
    for u, v, d in G.edges(data=True):
        rel = d.get('relation')
        if rel in ('targetADR', 'sourceADR'):
            decl = v if rel in ('targetADR', 'sourceADR') and G.nodes[v].get('type') == 'RelationDeclaration' else u
            if G.nodes[decl].get('relationType') in ('supersedes', 'superseded_by', 'replaces'):
                # Identificar el ADR reemplazante y verificar su recordDate
                replacing_adr = None
                for a, b, d2 in G.in_edges(decl, data=True):
                    if a != adr_id and G.nodes[a].get('type') == 'ArchitectureDecisionRecord':
                        replacing_adr = a
                if replacing_adr:
                    rep_date = G.nodes[replacing_adr].get('recordDate')
                    if rep_date and rep_date <= target_date:
                        return 'superseded'
    return status

def consulta(G, topic_name):
    # 1. Identificar el tema
    topics = [n for n, d in G.nodes(data=True) if d.get('type') == 'Topic' and d.get('topicName') == topic_name]
    if not topics:
        return None
    topic = topics[0]

    # 2. Obtener los ADRs que tratan dicho tema
    adrs = {u for u, v, d in G.edges(data=True) if d.get('relation') == 'addressesTopic' and v == topic}

    # 3. Reconstruir las relaciones de reemplazo entre estos ADRs
    # En el esquema, sourceADR/targetADR conectan ADR con RelationDeclaration
    replaces_edges = []
    rel_decls = [n for n, d in G.nodes(data=True) if d.get('type') == 'RelationDeclaration']
    for rel in rel_decls:
        rel_type = G.nodes[rel].get('relationType', '').lower()
        if any(keyword in rel_type for keyword in ['supersedes', 'replaces', 'superseded']):
            sources = [u for u, v, d in G.edges(data=True) if v == rel and d.get('relation') == 'sourceADR']
            targets = [u for u, v, d in G.edges(data=True) if v == rel and d.get('relation') == 'targetADR']
            if sources and targets:
                s, t = sources[0], targets[0]
                if s in adrs and t in adrs:
                    if 'superseded' in rel_type and 'superseded by' not in rel_type:
                        replaces_edges.append((t, s))
                    else:
                        replaces_edges.append((s, t))

    # 4. Encontrar la cadena de reemplazos y el ADR vigente (el que no ha sido reemplazado)
    replaced = {tgt for src, tgt in replaces_edges}
    active_adrs = [adr for adr in adrs if adr not in replaced]

    # 5. Obtener la decisión asociada al ADR vigente
    results = []
    for active_adr in active_adrs:
        decisions = [v for u, v, d in G.edges(data=True) if u == active_adr and d.get('relation') == 'recordsDecision']
        results.append({
            'active_adr': active_adr,
            'decision': decisions[0] if decisions else None,
            'replacement_chain': replaces_edges
        })
    return results
